# -*- coding: utf-8 -*-
"""苏轼趣闻 → people/sushi_fun.json
每条：标题、年份、年龄、地点、故事（白话）、出处、可信度（史实 / 笔记 / 传说）、标签、一句点评。
可信度：史实 = 他自己的诗文书信或正史里有；笔记 = 宋人笔记记载，大体可信但细节可能加工；传说 = 后世附会，当故事听。"""
import json, os
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
F = [
 ("名字里的心思", 1046, 9, "眉山", "爸爸苏洵给两个儿子起名，专门写了篇《名二子说》。轼是车前的扶手横木，看着没用，可少了它车就不像车——「吾惧汝之不外饰也」，怕你太张扬、不懂掩饰。辙是车轮压出的印子，车翻了马死了都怪不到它头上——弟弟一辈子稳当，果然比哥哥少吃很多苦。", "苏洵《名二子说》", "史实", ["家人"], "知子莫若父：一个名字，几乎写尽了两兄弟的一生。"),
 ("「想当然耳」", 1057, 20, "汴京", "二十岁考进士，文章里写了个典故：尧的时候皋陶三次要判人死刑，尧三次赦免。考官梅尧臣读得叫好，却想不起出处。放榜后问他，苏轼答：「想当然耳。」——是我照尧的为人推想出来的。主考欧阳修听了大笑，反而更欣赏他。", "宋人笔记（如杨万里《诚斋诗话》）", "笔记", ["才气"], "「想当然」这个成语就是这么来的。放到今天，算是考场上最大胆的一次瞎编。"),
 ("欧阳修：我该给他让路了", 1057, 20, "汴京", "文坛领袖欧阳修读了苏轼的文章，给朋友梅尧臣写信说：「读轼书，不觉汗出，快哉快哉！老夫当避路，放他出一头地也。」——我该让开路，让这个年轻人高出一头。「出人头地」这个说法，就是从这儿来的。", "欧阳修《与梅圣俞书》", "史实", ["才气", "交友"], "前辈愿意给后辈让路，是苏轼一生遇到的第一份好运。"),
 ("王弗屏风后听人", 1060, 23, "凤翔", "第一任妻子王弗很聪明。苏轼待人没心眼，跟谁都掏心窝子。客人来时，王弗常躲在屏风后听，客人走了就提醒他：「这人说话总顺着你的意思，不必跟他多交往。」后来那些人果然都靠不住。她 27 岁去世，十年后苏轼梦见她，写下「十年生死两茫茫」。", "苏轼《亡妻王氏墓志铭》", "史实", ["家人"], "天下最懂他的人走得最早，所以那首《江城子》才那么疼。"),
 ("「子厚必能杀人」", 1062, 25, "凤翔", "年轻时和章惇同游，到一处绝壁，下面是深涧，只有一根独木桥。章惇面不改色走过去，在对面石壁上写下「苏轼章惇来」，又走回来。苏轼拍着他的背说：「你以后一定会杀人。」——一个连自己命都不在乎的人，也不会在乎别人的命。多年后章惇当了宰相，把苏轼一路贬到了海南。", "宋人笔记", "笔记", ["看人"], "一句玩笑，几十年后应验在自己身上。"),
 ("一碗「毳饭」", 1070, 33, "汴京", "朋友刘攽爱开玩笑。苏轼跟他说，我们兄弟读书时天天吃「三白饭」，还觉得香。问是啥——一撮盐、一碟生萝卜、一碗白饭。刘攽记下了。过几天请苏轼吃「皛饭」，端上来果然就是盐、萝卜、饭三样。苏轼回请他吃「毳饭」，刘攽饿着肚子等到傍晚，什么都没上。苏轼说：盐也毛（没）、萝卜也毛、饭也毛——三毛，就是「毳」。", "朱弁《曲洧旧闻》", "笔记", ["怼人", "交友"], "被耍了一次，记着，换个字耍回来。"),
 ("苏堤", 1090, 53, "杭州", "第二次到杭州当知州，西湖已经被葑草淤塞了一半。他给朝廷上书说「杭州之有西湖，如人之有眉目」，动用二十万民工疏浚，把挖出来的淤泥和葑草堆成一条横跨湖面的长堤，堤上种柳树、建六座桥。这就是今天的苏堤，「苏堤春晓」是西湖十景的第一景。", "《宋史·苏轼传》、苏轼《乞开杭州西湖状》", "史实", ["做实事"], "诗人当官，留下的不只是诗。"),
 ("东坡肉的两个版本", 1082, 45, "黄州", "被贬黄州时他写了《猪肉颂》：黄州猪肉好，便宜得像泥土，富人不肯吃，穷人不会煮。「慢着火，少着水，火候足时他自美。」——这是真的。至于在杭州疏浚西湖，百姓送来猪肉，他让人做成红烧肉分给民工，大家叫它「东坡肉」——这是后来的民间说法。", "苏轼《猪肉颂》；杭州故事为民间传说", "史实", ["美食"], "穷的时候把便宜货吃出名堂，这本事比做菜更难得。"),
 ("乌台诗案里的一条鱼", 1079, 42, "汴京御史台狱", "因为诗文被指讽刺朝政，他被抓进御史台大狱，差点被杀。他跟送饭的长子苏迈约好：平常送菜和肉，要是听到要判死刑，就送鱼。有一天苏迈出去借钱，托亲戚代送饭，亲戚不知情，送了一条熏鱼。苏轼以为死期到了，给弟弟写下两首诀别诗：「与君世世为兄弟，更结人间未了因。」", "宋人笔记；诀别诗为苏轼《狱中寄子由》", "笔记", ["苦难", "家人"], "生死关头，他最放不下的是弟弟：下辈子还要做兄弟。"),
 ("连王安石都替他求情", 1079, 42, "汴京", "乌台诗案时，苏轼的政敌王安石已经退居金陵。据说他上书神宗：「岂有圣世而杀才士者乎？」——哪有太平盛世杀有才之人的道理。苏轼最后免死，贬去黄州。五年后两人在金陵见面，同游钟山，谈诗论佛好多天。王安石感叹：「不知更几百年，方有如此人物。」", "宋人笔记", "笔记", ["交友"], "政见可以吵一辈子，人品和才华却能互相认。"),
 ("把钱挂在房梁上", 1080, 43, "黄州", "黄州没有俸禄，一家人吃饭成了问题。他想了个办法：每月初拿出四千五百钱，分成三十串挂在房梁上，每天早上用画画的叉子挑下一串，就是当天的开销，剩下的放进大竹筒，留着招待客人。写信给朋友秦观说：这样「可支一岁有余」，到时候再想办法。", "苏轼《答秦太虚书》", "史实", ["苦中作乐"], "穷也穷得有章法、有幽默。"),
 ("「河东狮吼」原来是朋友家的事", 1080, 43, "黄州", "好友陈慥（字季常）爱谈佛、好宾客，夫人柳氏脾气厉害。苏轼写诗打趣他：「忽闻河东狮子吼，拄杖落手心茫然。」柳姓郡望在河东，「狮子吼」是佛经里的词，正好嘲笑这位谈佛的朋友一听夫人发火就吓掉了拐杖。后来「河东狮吼」就成了形容凶老婆的成语。", "苏轼《寄吴德仁兼简陈季常》", "史实", ["怼人", "交友"], "调侃朋友调侃出一个成语，陈季常大概哭笑不得。"),
 ("「何夜无月」", 1083, 46, "黄州承天寺", "一个十月的夜里，他已经脱衣要睡，看见月光照进门来，高兴得起身出门。想到没人一起玩，就去承天寺找同样被贬的张怀民。张也还没睡，两人在院子里散步，地上的竹柏影子像水里的水草。他写道：「何夜无月？何处无竹柏？但少闲人如吾两人者耳。」", "苏轼《记承天寺夜游》", "史实", ["苦中作乐", "交友"], "「闲人」是被贬的自嘲，也是只有他们才看得到这月色的骄傲。"),
 ("「小舟从此逝」吓坏了太守", 1082, 45, "黄州", "一天夜里在东坡喝酒，回到临皋住处已经三更，家童睡着了，敲门不应，他就站在江边听涛声，写了一首《临江仙》，最后两句是「小舟从此逝，江海寄余生」。第二天满城传说苏轼写完这首词，把帽子衣服挂在江边，坐船跑了。太守吓得赶紧去看——苏轼正在屋里鼾声如雷。", "叶梦得《避暑录话》", "笔记", ["苦中作乐"], "想逃是真的想，但他从来没逃。"),
 ("一肚皮不合时宜", 1085, 48, "汴京", "一次吃完饭，他摸着肚子问家里的侍女：「你们说这里面装的是什么？」一个说是文章，一个说是见识，他都摇头。侍妾王朝云说：「学士一肚皮不合入时宜。」苏轼捧腹大笑。王安石当权时他反对新法，司马光上台他又反对尽废新法，两边都不讨好。", "费衮《梁溪漫志》", "笔记", ["看人", "家人"], "最懂他的人，一句话说穿了他的一辈子。"),
 ("「高处不胜寒」打动了皇帝", 1076, 39, "密州", "中秋写给弟弟的《水调歌头》传到京城，宋神宗读到「我欲乘风归去，又恐琼楼玉宇，高处不胜寒」，叹了一句：「苏轼终是爱君。」据说后来把他从黄州调到离京城近一些的汝州，就和这件事有关。", "宋人笔记", "笔记", ["才气"], "一首想弟弟的词，被皇帝读成了想朝廷。"),
 ("石压蛤蟆，树梢挂蛇", 1086, 49, "汴京", "苏轼和学生黄庭坚都是大书法家，常互相取笑。苏轼说黄庭坚的字太瘦，「几如树梢挂蛇」；黄庭坚回嘴说老师的字扁，「甚似石压蛤蟆」。两人哈哈大笑，都觉得说中了对方的毛病。", "曾敏行《独醒杂志》", "笔记", ["怼人", "交友"], "师生能这样互损，说明是真朋友。"),
 ("陪得了玉皇，也陪得了乞丐", 1080, 43, "黄州", "他跟弟弟说过：「吾上可陪玉皇大帝，下可陪卑田院乞儿。眼前见天下无一个不好人。」上到皇帝宰相，下到乞丐、农夫、和尚、渔夫，他都能聊到一块儿去。", "高文虎《蓼花洲闲录》", "笔记", ["看人"], "被人害了那么多次，还觉得天下没有一个不好的人。"),
 ("佛印和「一屁打过江」", 1080, 43, "黄州 / 镇江金山", "据说苏轼写了首得意的偈子「八风吹不动，端坐紫金莲」，派人过江送给佛印禅师看。佛印只批了两个字：「放屁。」苏轼大怒，过江找他理论，佛印笑说：「八风吹不动，一屁打过江。」苏轼才知道自己被将了一军。——苏轼确实和佛印交好，但这个故事是明清人编的。", "明清民间故事", "传说", ["交友"], "当笑话听正好；当史料就不行了。"),
 ("苏小妹是谁", 1060, 23, "眉山", "民间有很多「苏小妹三难新郎」「苏小妹嫁秦少游」的故事，说她比哥哥还聪明。其实苏轼没有叫苏小妹的妹妹：他有个姐姐苏八娘，嫁到程家受了欺负，十八岁就去世了。秦观的妻子姓徐。苏小妹是明代小说《醒世恒言》塑造的人物。", "冯梦龙《醒世恒言》；苏八娘事见苏洵诗文", "传说", ["家人"], "传说替苏家添了一个快乐的女儿，真实的那个姐姐却早早走了。"),
 ("日啖荔枝三百颗", 1095, 58, "惠州", "六十岁前后被贬到岭南惠州，当时那里是瘴疠之地。他第一次吃到新鲜荔枝，高兴得写诗：「日啖荔枝三百颗，不辞长作岭南人。」——每天吃三百颗荔枝，让我一辈子当岭南人也愿意。（三百颗是夸张，但喜欢是真的。）", "苏轼《惠州一绝》", "史实", ["美食", "苦中作乐"], "别人看是流放，他看是吃荔枝的机会。"),
 ("惠州的羊脊骨", 1094, 57, "惠州", "惠州市场每天只杀一只羊，好肉轮不到他这个罪官。他就跟屠户买没人要的羊脊骨，煮熟后泡点酒、撒点盐，烤得微焦，用牙签慢慢剔骨缝里的碎肉吃。写信跟弟弟炫耀：吃起来像吃蟹螯，「三五日辄一食，甚觉有补」——就是苦了狗，「众狗不悦矣」。", "苏轼《与子由弟书》", "史实", ["美食", "苦中作乐"], "据说这就是「羊蝎子」的祖师爷。"),
 ("酿酒喝坏了肚子", 1095, 58, "惠州", "他在岭南兴致勃勃自己酿酒，酿过「真一酒」「桂酒」，还写了文章介绍方法。后来有人说，喝过他酿的酒的人，常常闹肚子。", "宋人笔记", "笔记", ["美食"], "做菜是一流，酿酒大概是三流。"),
 ("把皇帝赏的腰带捐了修桥", 1096, 59, "惠州", "惠州百姓过江过湖全靠浮桥小船，常出事。苏轼自己没钱，就把当年皇帝赏的犀角腰带捐了出来，又写信请弟弟一家帮忙，弟媳捐出了宫里赏的金钱，修成东、西两座新桥。桥修好那天，全城百姓欢庆了三天。", "苏轼《两桥诗》并引", "史实", ["做实事"], "被贬到最南边，没有官权，也要想办法给老百姓做点事。"),
 ("一场春梦", 1098, 61, "儋州（海南）", "在海南，他头戴大瓢在田里边走边唱，遇到一位七十多岁的老妇。老妇说：「内翰昔日富贵，一场春梦。」——您当年的荣华富贵，不过一场春梦啊。苏轼深以为然，从此叫她「春梦婆」。", "赵令畤《侯鲭录》", "笔记", ["看人", "苦中作乐"], "一个乡下老太太，一句话点醒了大学士。"),
 ("生蚝不要告诉别人", 1098, 61, "儋州（海南）", "到了海南，他吃到生蚝，烤着吃、煮着吃，觉得天下美味。写信给儿子苏过：「无令中朝士大夫知，恐争谋南徙，以分此味。」——千万别让朝廷里的大官们知道，不然他们都争着要被贬到海南来，跟我抢生蚝吃。", "苏轼《献蚝帖》（《食蚝》）", "史实", ["美食", "苦中作乐"], "被贬到天涯海角，还担心别人来抢他的吃的。"),
 ("东坡羹", 1081, 44, "黄州", "没钱吃肉的时候，他用白菜、萝卜、荠菜、米，加一点生姜，不放油不放酱，煮成一锅菜羹，取名「东坡羹」，还写了《东坡羹颂》，说它「有自然之味」，能让吃惯大鱼大肉的人也觉得好吃。", "苏轼《东坡羹颂》并引", "史实", ["美食", "苦中作乐"], "最便宜的菜，也要起个好名字、写篇文章。"),
 ("「个里着力不得」", 1101, 64, "常州", "从海南遇赦北归，走到常州病倒。临终时老朋友维琳方丈在他耳边大声说：「端明宜勿忘西方！」——别忘了往西方极乐世界去。他回答：「西方不无，但个里着力不得。」——西方或许有，可这件事使劲是使不上的。旁人又劝他用力想，他说：「着力即差。」说完就走了。", "宋人笔记", "笔记", ["看淡生死"], "一辈子用力地活，到最后懂得了不用力。"),
]
out = []
for i, f in enumerate(F):
    t, y, a, pl, story, src, cred, tags, why = f
    assert cred in ("史实", "笔记", "传说"), t
    out.append({"id": "f%02d" % (i + 1), "title": t, "year": y, "age": a, "place": pl, "story": story, "src": src, "cred": cred, "tags": tags, "why": why})
out.sort(key=lambda x: x["year"])
with open(os.path.join(ROOT, "people", "sushi_fun.json"), "w", encoding="utf-8") as fh:
    json.dump({"items": out}, fh, ensure_ascii=False, separators=(",", ":"))
print("people/sushi_fun.json:", len(out))
